// =======================================================
// Extrai erros usando SOMENTE o payload do Error Trigger
// Fonte única: nó "Acionador de Erro"
// =======================================================

// 1) Payload bruto do Error Trigger (referenciado)
const errorTrigger = $('Acionador de Erro').item.json;

// 2) Execução e workflow
const execution = errorTrigger.execution || {};
const workflow  = errorTrigger.workflow || {};
const err       = execution.error || {};

// 3) Metadata da execução
const meta = {
  executionId: execution.id || null,
  mode: execution.mode || null,
  finished: true,

  workflowId: workflow.id || null,
  workflowName: workflow.name || null,

  lastNodeExecuted: execution.lastNodeExecuted || null,
  source: execution.executionContext?.source || null,

  startedAt: execution.executionContext?.establishedAt
    ? new Date(execution.executionContext.establishedAt).toISOString()
    : null,
};

// 4) Metadata do erro
const nodeDef = err.node || {};

const errorItem = {
  ...meta,

  nodeName: nodeDef.name || meta.lastNodeExecuted,
  nodeId: nodeDef.id || null,
  nodeType: nodeDef.type || null,

  errorName: err.name || null,
  errorMessage: err.message || null,
  errorDescription: err.description || null,
  messages: err.messages || null,
  context: err.context || null,
  stack: err.stack || null,

  parameters: nodeDef.parameters || null,
};

// 5) Retorno padronizado (1 erro = 1 item)
return [
  {
    json: errorItem
  }
];

// ✅ ENTRADA: mesmo payload que você já usa (objeto ou string JSON)
// ✅ SAÍDA: { subject, html, whatsapp_message, whatsapp_message_ultra, count }

// 0) Utilidades
const tz = 'America/Sao_Paulo';
const trunc = (s, n) => {
  if (!s) return '-';
  const str = String(s).replace(/\s+/g, ' ').trim();
  return str.length <= n ? str : str.slice(0, n - 1).trimEnd() + '…';
};
const firstSentence = (s, n = 160) => {
  if (!s) return '-';
  const clean = String(s).replace(/\s+/g, ' ').trim();
  const m = clean.match(/(.+?[.!?])\s|$/);
  const pick = m && m[1] ? m[1].trim() : clean;
  return trunc(pick, n);
};
const fmtDate = (iso) => {
  if (!iso) return '-';
  try {
    return new Date(iso).toLocaleString('pt-BR', { timeZone: tz });
  } catch { return '-'; }
};

// 1) Lê o payload de erro SEM modificar o JSON de entrada
const rawInput = items[0].json;
const parsed = typeof rawInput === 'string' ? JSON.parse(rawInput) : rawInput;
const errorArray = Array.isArray(parsed) ? parsed : [parsed];

// 2) Monta o HTML (PT-BR) usando somente leitura dos campos existentes (SEU HTML MANTIDO)
let htmlSections = '';

for (const errObj of errorArray) {
  const {
    error: {
      workflowName,
      executionId,
      nodeName,
      previousNode,
      diagnosis,
      cause,
      resolution,
      startedAt,
    } = {},
    workflowLink,
    executionLink,
  } = errObj;

  const prev = (previousNode ?? '-') + '';
  const startedStr = startedAt
    ? new Date(startedAt).toLocaleString('pt-BR', { timeZone: tz })
    : '-';

  htmlSections += `
    <div style="border:1px solid #ddd;border-radius:4px;padding:16px;margin-bottom:20px;background:#fafafa;">
      <h3 style="margin:0 0 10px;color:#c0392b;font-family:Arial,sans-serif;">
        🛑 ${workflowName} — erro no nó: ${nodeName}
      </h3>
      <p style="margin:4px 0;font-family:Arial,sans-serif;">
        <strong>Workflow:</strong>
        <a href="${workflowLink}" style="color:#2980b9;text-decoration:none;">${workflowName}</a><br/>
        <strong>Execução:</strong>
        <a href="${executionLink}" style="color:#2980b9;text-decoration:none;">#${executionId}</a><br/>
        <strong>Nó anterior:</strong> ${prev}<br/>
        <strong>Início:</strong> ${startedStr}
      </p>
      <hr style="border:none;border-top:1px solid #ccc;margin:12px 0;"/>
      <h4 style="margin:0 0 6px;color:#e67e22;font-family:Arial,sans-serif;">🔍 Diagnóstico</h4>
      <p style="margin:4px 0 12px;font-family:Arial,sans-serif;">${diagnosis ?? '-'}</p>
      <h4 style="margin:0 0 6px;color:#e67e22;font-family:Arial,sans-serif;">⚙️ Causa</h4>
      <p style="margin:4px 0 12px;font-family:Arial,sans-serif;">${cause ?? '-'}</p>
      <h4 style="margin:0 0 6px;color:#27ae60;font-family:Arial,sans-serif;">✅ Solução</h4>
      <p style="white-space:pre-wrap;margin:4px 0;font-family:Arial,sans-serif;">${resolution ?? '-'}</p>
    </div>`;
} // fecha o for

// 3) Cabeçalho do email
const first = errorArray[0]?.error || {};
const subject = `🚨 Erro no n8n: ${first.workflowName || '-'} (#${first.executionId || '-'})`;

// 4) HTML final
const html = `
  <div style="font-family:Arial,sans-serif;color:#333;background:#fff;padding:20px;">
    <h2 style="margin-top:0;color:#2c3e50;">Relatório Automático de Erro</h2>
    ${htmlSections}
  </div>
`;

// 5) MENSAGENS PARA WHATSAPP (concisa e ultra)
const blocks = errorArray.map((e) => {
  const err = e.error || {};
  const started = fmtDate(err.startedAt);
  const workflow = err.workflowName || '-';
  const node = err.nodeName || '-';
  const prev = (err.previousNode ?? '-') + '';
  const execId = err.executionId ? `#${err.executionId}` : '-';
  const diagnosis = trunc(err.diagnosis || '-', 200);
  const cause = trunc(err.cause || '-', 160);
  const resolution = firstSentence(err.resolution || '-', 180);

  const execLink = e.executionLink || '';
  // const wfLink = e.workflowLink || ''; // opcional

  // Versão "concisa"
  const concise = [
    `🛑 *${workflow}*`,
    `Nó: *${node}* ${prev && prev !== '-' ? `(prev: ${prev})` : ''}`.trim(),
    `Execução: *${execId}*${execLink ? `\n🔗 ${execLink}` : ''}`,
    `Início: ${started}`,
    diagnosis && diagnosis !== '-' ? `🔍 ${diagnosis}` : null,
    cause && cause !== '-' ? `⚙️ ${cause}` : null,
    resolution && resolution !== '-' ? `✅ ${resolution}` : null,
  ].filter(Boolean).join('\n');

  // Versão "ultra"
  const ultra = [
    `🛑 ${trunc(workflow, 48)} | ${trunc(node, 24)} | ${execId}`,
    resolution && resolution !== '-' ? `✅ ${trunc(resolution, 90)}` : (diagnosis && diagnosis !== '-' ? `🔍 ${trunc(diagnosis, 90)}` : null),
    execLink ? `🔗 ${execLink}` : null,
  ].filter(Boolean).join('\n');

  return { concise, ultra };
});

const sep = '\n— — —\n';
const whatsapp_message = blocks.map(b => b.concise).join(sep);
const whatsapp_message_ultra = blocks.map(b => b.ultra).join('\n');

// 6) Retorno único com tudo
return [{
  json: {
    subject,
    html,
    whatsapp_message,
    whatsapp_message_ultra,
    count: errorArray.length
  }
}];

// Timezone local
const tz = 'America/Sao_Paulo';

// Pega horário atual em SP
const now = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const hour = now.getHours();

// Permite rodar se NÃO estiver entre 02:00–02:59
const canProcess = !(hour === 2);

return [{
  json: {
    canProcess,
    now: now.toISOString(),
    hourLocal: hour,
    tz
  }
}];

// ===========================================
// Filtro de Deduplicação (Smart Debounce)
// ===========================================

const itemsToProcess = [];
const WINDOW_MS = 10 * 60 * 1000; // 10 minutos

let lastErrors = {};
let useStatic = false;
let staticDataReference;

try {
    // Tenta acessar dados estáticos globais usando a sintaxe Nova ($)
    staticDataReference = $getWorkflowStaticData('global');
    lastErrors = staticDataReference.lastErrors || {};
    useStatic = true;
} catch (e) {
    try {
        // Fallback para sintaxe antiga (sem $)
        staticDataReference = getWorkflowStaticData('global');
        lastErrors = staticDataReference.lastErrors || {};
        useStatic = true;
    } catch (e2) {
         console.log("Aviso: Static Data indisponível. Debounce desativado.");
    }
}

const now = Date.now();

for (const item of items) {
  const err = item.json;

  // Chave Única
  const key = `${err.workflowId}:${err.nodeName}:${err.errorMessage}`;

  const lastSeen = lastErrors[key] || 0;

  if (now - lastSeen > WINDOW_MS) {
    // Processar este item
    itemsToProcess.push(item);

    // Atualiza tabela local
    lastErrors[key] = now;
  }
}

// Persistir se possível
if (useStatic && staticDataReference) {
    // Limpeza
    const cleanErrors = {};
    for (const k in lastErrors) {
      if (Date.now() - lastErrors[k] < WINDOW_MS) {
        cleanErrors[k] = lastErrors[k];
      }
    }
    staticDataReference.lastErrors = cleanErrors;
}

return itemsToProcess;

// Tenta recuperar dados do usuario do contexto global
const userPhone = $execution.customData?.userPhone;
const userName = $execution.customData?.userName || 'Usuário';

return {
    json: {
        userPhone,
        userName,
        hasUser: !!userPhone
    }
};

